import{_ as o,a0 as p,w as d,s as r,I as t,x as i,a1 as e,A as l,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"10 个在 Linux 终端中生成有趣的 ASCII 字符画的工具 | LCTT x X-CMD","titleTemplate":false,"description":"10 个在 Linux 终端中生成有趣的 ASCII 字符画的工具 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10 个在 Linux 终端中生成有趣的 ASCII 字符画的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10 个在 Linux 终端中生成有趣的 ASCII 字符画的工具 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20220706 10 Tools to Generate and Have Fun With ASCII Art in Linux Terminal","title":"10 个在 Linux 终端中生成有趣的 ASCII 字符画的工具","tag":"202309","desc":""},"relativePath":"202309/20220706 10 Tools to Generate and Have Fun With ASCII Art in Linux Terminal.md","filePath":"[post].md"}'),h={name:"202309/20220706 10 Tools to Generate and Have Fun With ASCII Art in Linux Terminal.md"};function u(g,s,c,k,b,f){const a=p("Link");return d(),r("div",null,[s[33]||(s[33]=t("h1",{id:"_10-个在-linux-终端中生成有趣的-ascii-字符画的工具",tabindex:"-1"},[i("10 个在 Linux 终端中生成有趣的 ASCII 字符画的工具 "),t("a",{class:"header-anchor",href:"#_10-个在-linux-终端中生成有趣的-ascii-字符画的工具","aria-label":"Permalink to “10 个在 Linux 终端中生成有趣的 ASCII 字符画的工具”"},"​")],-1)),s[34]||(s[34]=t("blockquote",null,[t("p",null,"以为 Linux 终端都是严肃的工作？想多了。以下是你可以在终端中使用 ASCII 字符画做的几件趣事。")],-1)),t("p",null,[s[1]||(s[1]=i("Linux 终端其实没有想象中的那样 ",-1)),e(a,{href:"https://itsfoss.com/basic-terminal-tips-ubuntu/"},{default:l(()=>[...s[0]||(s[0]=[i("可怕",-1)])]),_:1}),s[2]||(s[2]=i("。",-1))]),t("p",null,[s[4]||(s[4]=i("当然啦，一开始它可能会令人望而却步，但是当我们更 ",-1)),e(a,{href:"https://itsfoss.com/love-thy-terminal/"},{default:l(()=>[...s[3]||(s[3]=[i("了解",-1)])]),_:1}),s[5]||(s[5]=i(" 它的时候，我们就会喜欢上它的。",-1))]),s[35]||(s[35]=n('<p>你可能会使用终端来做一些严肃的工作。不过，你也可以在终端中做很多有趣的事情。</p><p>其中的一项就是试一试<ruby>ASCII 字符画<rt>ASCII art</rt></ruby>。你可以在 Linux 终端中用各种命令行工具以 ASCII 的形式显示一些预定义的或是随机的消息、玩游戏，抑或是播放动画。</p><p>我的同事 Sreenath 喜欢探索此类不寻常的命令行工具并将他的发现分享给我。现在，我也将他的发现与你分享。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/ascii-art-tools-linux.png" alt="ascii art tools linux"></p><p>你的 Linux 发行版的仓库中应该已经有这些程序中的大多数了。你可以用系统的包管理器安装它们。为了使文章简洁，下文的安装指南均以 Ubuntu 为例。</p><h3 id="_1、lolcat-向终端加入缤纷色彩" tabindex="-1">1、lolcat：向终端加入缤纷色彩 <a class="header-anchor" href="#_1、lolcat-向终端加入缤纷色彩" aria-label="Permalink to “1、lolcat：向终端加入缤纷色彩”">​</a></h3><p>虽然 <code>lolcat</code> 与 ASCII 字符画没有任何关系，至少，没有直接关系。</p><p>但是，我还是在文章开头就列出了它，因为它可以与其他的 ASCII 工具组合使用。</p><p>所以，它能做什么呢？它与 <code>cat</code> 指令很相似，但是它向输出内容加入随机的渐变色彩。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/lolcat.png" alt="lolcat"></p><p>目前它看起来可能没什么用，但当其他 ASCII 工具通过 <code>lolcat</code> 输出时，你会看到它的效果。</p><p>用 <code>apt</code> 安装 <code>lolcat</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install lolcat</span></span></code></pre></div><h3 id="_2、aewan-漂亮地显示-ascii-字符" tabindex="-1">2、Aewan：漂亮地显示 ASCII 字符 <a class="header-anchor" href="#_2、aewan-漂亮地显示-ascii-字符" aria-label="Permalink to “2、Aewan：漂亮地显示 ASCII 字符”">​</a></h3><p>Aewan 是一个多层 ASCII 图形、动画编辑器。它可以生成独立的，可被 <code>cat</code> 命令查看的 ASCII 字符画文件和便于命令行工具集成与解析的格式。</p><p>它包括两个工具：ASCII 编辑器 <code>aewan</code>，和文件查看器 <code>aecat</code>。</p><p>这里不讨论编辑器部分。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/Aewan-initial-layout.png" alt="aewan 的初始状态布局"></p><p>用 <code>aecat</code> 命令以 ASCII 格式漂亮地显示任何文本。注意下面的截屏中字母的使用方式。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/aewan-output.png" alt="aewan output"></p><p>用下面的命令安装 <code>aewan</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install aewan</span></span></code></pre></div><p>然后这样使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>aecat hello</span></span></code></pre></div><h3 id="_3、cowsay-让-ascii-牛复述你想说的话" tabindex="-1">3、Cowsay：让 ASCII 牛复述你想说的话 <a class="header-anchor" href="#_3、cowsay-让-ascii-牛复述你想说的话" aria-label="Permalink to “3、Cowsay：让 ASCII 牛复述你想说的话”">​</a></h3><p>这头牛在说什么？你想什么就让它说什么。</p><p><code>cowsay</code> 是经验丰富的 Linux 用户中流行的工具。它显示了一个 ASCII 格式的牛，会重复你提供的文本。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/cowsay-1.png" alt="cowsay"></p><p>但不仅限于牛。你也可以将其更改为其他的角色。比如，一条龙（火龙君临）：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/cowsay.png" alt="cowsay"></p><p>你注意到截图中的色彩了吗？这正是上文提到过的 <code>lolcat</code> 命令的魔力所在。</p><p>用下列命令安装 <code>cowsay</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install cowsay</span></span></code></pre></div><p>装好之后，这样使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cowsay hello</span></span></code></pre></div>',35)),t("p",null,[s[7]||(s[7]=i("你可以参考它的 ",-1)),e(a,{href:"https://itsfoss.com/linux-man-page-guide/"},{default:l(()=>[...s[6]||(s[6]=[i("手册",-1)])]),_:1}),s[8]||(s[8]=i("，浏览其他配置和选项。",-1))]),s[36]||(s[36]=n('<h3 id="_4、jp2a-图片转-ascii-字符画" tabindex="-1">4、jp2a：图片转 ASCII 字符画 <a class="header-anchor" href="#_4、jp2a-图片转-ascii-字符画" aria-label="Permalink to “4、jp2a：图片转 ASCII 字符画”">​</a></h3><p><code>jp2a</code> 是一个在 Linux 终端中将图像转换为 ASCII 字符画的命令行工具。它适用于 JPEG 和 PNG 文件，允许彩色输出和用你选定的字符显示 ASCII 字符画。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/jp2a.png" alt="jp2a"></p><p>用下列命令安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install jp2a</span></span></code></pre></div><p>你可以像这样得到彩色的输出，并且保存到文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>jp2a --output=ascii.txt --colors input.png</span></span></code></pre></div><p>它并不是这类工具中的唯一一种，比如，<code>ascii-image-converter</code> 和几个其他的工具也可以达成相同的效果。在这里不再一一讨论了。</p><h3 id="_5、linuxlogo-用-ascii-格式显示-linux-发行版的徽标" tabindex="-1">5、linuxlogo：用 ASCII 格式显示 Linux 发行版的徽标 <a class="header-anchor" href="#_5、linuxlogo-用-ascii-格式显示-linux-发行版的徽标" aria-label="Permalink to “5、linuxlogo：用 ASCII 格式显示 Linux 发行版的徽标”">​</a></h3>',9)),t("p",null,[s[10]||(s[10]=i("正如起名，它 ",-1)),e(a,{href:"https://itsfoss.com/display-linux-logo-in-ascii/"},{default:l(()=>[...s[9]||(s[9]=[i("用 ASCII 格式显示 Linux 发行版的标志",-1)])]),_:1}),s[11]||(s[11]=i("。",-1))]),t("p",null,[s[13]||(s[13]=i("不，不是我们 ",-1)),e(a,{href:"https://itsfoss.com/tux-trivia/"},{default:l(()=>[...s[12]||(s[12]=[i("喜爱的 Linux 标志 Tux",-1)])]),_:1}),s[14]||(s[14]=i("，而是你的 Linux 发行版的徽标。它还显示一些其他信息，比如 Linux 内核版本、CPU、RAM、主机名等等。",-1))]),s[37]||(s[37]=n('<p><img src="https://itsfoss.com/content/images/wordpress/2022/07/linux-logo.png" alt="linux logo"></p><p>用 <code>apt</code> 安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install linuxlogo</span></span></code></pre></div><p>输入 <code>linuxlogo</code> 就可以用啦。</p><h3 id="_6、neoftech-显示-linux-标志和系统信息" tabindex="-1">6、Neoftech：显示 Linux 标志和系统信息 <a class="header-anchor" href="#_6、neoftech-显示-linux-标志和系统信息" aria-label="Permalink to “6、Neoftech：显示 Linux 标志和系统信息”">​</a></h3><p>上面的 Linux 标志有点太简化了。你可以用 Neofetch 放大它。</p><p>它以更漂亮的方式显示发行版以及一些系统信息，如内核、运行时间、桌面环境、主题和图标等等。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/neofetch.png" alt="neofetch"></p><p>你还可以通过 <code>lolcat</code> 解析它，获得彩虹色的输出。</p><p>用这行命令安装 Neofetch：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install neofetch</span></span></code></pre></div><p>然后，输入 <code>neofetch</code> 就可以运行啦。</p><p>还有一个与 Neofetch 很像的工具，<code>screenfetch</code>。用哪个都行。</p><h3 id="_7、fortune-看看命运如何" tabindex="-1">7、fortune：看看命运如何 <a class="header-anchor" href="#_7、fortune-看看命运如何" aria-label="Permalink to “7、fortune：看看命运如何”">​</a></h3><p>开玩笑啦。这样的事情根本就不存在。</p><p>不过，幸运饼干仍然很流行，所以显然，人们喜欢阅读随机的预测或说法。</p><p>你可以在 Linux 终端中用 Fortune 命令达到类似效果：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/fortune-cookie-Linux.png" alt="fortune cookie linux"></p><p>你可以用下面的命令安装它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install fortune</span></span></code></pre></div><p>装好之后，在终端中输入 <code>fortune</code> 来得到一条随机消息。</p><h3 id="_8、pv-让一切动起来" tabindex="-1">8、pv：让一切动起来 <a class="header-anchor" href="#_8、pv-让一切动起来" aria-label="Permalink to “8、pv：让一切动起来”">​</a></h3><p>这是非预期使用 Linux 命令的典型例子。<code>pv</code> 命令本来用于通过管道监控数据的进度。</p><p>但你可以使用它来对显示任何命令的输出加入动画效果。将其与上述的命令结合起来，你就可以看到 ASCII 字符画逐渐显现在屏幕上，就像正在输入一样。</p><p>不太明白？看看这个：</p><p><img src="https://player.vimeo.com/video/727286686" alt="A Video from YouTube"></p><p>用下面的命令安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install pv</span></span></code></pre></div><p>然后按这样使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>neofetch | pv -qL 200 | lolcat</span></span></code></pre></div><p>数字越大，速度越快。</p><h3 id="_9、cmatrix-类似黑客帝国的-ascii-动画" tabindex="-1">9、cmatrix：类似黑客帝国的 ASCII 动画 <a class="header-anchor" href="#_9、cmatrix-类似黑客帝国的-ascii-动画" aria-label="Permalink to “9、cmatrix：类似黑客帝国的 ASCII 动画”">​</a></h3><p>还记得 “黑客帝国” 吗？下落的绿色代码是黑客帝国和黑客的象征。</p><p>你可以使用 <code>cmatrix</code> 命令在 Linux 终端用 ASCII 模拟运行下落代码。</p><p>我在这里用一张图片代替视频。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/cmatrix.png" alt="cmatrix"></p><p>你可以用 <code>apt</code> 安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install cmatrix</span></span></code></pre></div><p>安装好之后，用它运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cmatrix</span></span></code></pre></div><p>它会立即启动，并不断生成随机的绿色文本，带着从屏幕上落下后消失的动画效果。该命令会持续运行。使用 <code>Ctrl+C</code> 停止运行程序。</p><h3 id="_10、cbonsai-在你的终端种植盆景" tabindex="-1">10、cbonsai：在你的终端种植盆景 <a class="header-anchor" href="#_10、cbonsai-在你的终端种植盆景" aria-label="Permalink to “10、cbonsai：在你的终端种植盆景”">​</a></h3><p>有没有园艺的天赋？在终端中种植一棵 ASCII 盆景树怎么样？</p><p><code>cbonsai</code> 是一个可让你以 ASCII 格式运行盆景树生长动画的有趣 Linux 命令。</p><p>几天前我发了一条关于 <code>cbonsai</code> 命令的 YouTube 短视频。</p><p><img src="https://youtu.be/KqhqgdezPp8" alt="Have fun with the Linux terminal 😍 🐧"></p><p>你可以用下面的命令安装 <code>cbonsai</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install cbonsai</span></span></code></pre></div><p>用这行命令运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cbonsai -l</span></span></code></pre></div><h3 id="试试更多" tabindex="-1">试试更多 <a class="header-anchor" href="#试试更多" aria-label="Permalink to “试试更多”">​</a></h3>',51)),t("p",null,[s[16]||(s[16]=i("还有很多这样的有趣的命令行工具，甚至还有 ",-1)),e(a,{href:"https://itsfoss.com/best-ascii-games/"},{default:l(()=>[...s[15]||(s[15]=[i("ASCII 游戏",-1)])]),_:1}),s[17]||(s[17]=i("。有时，看着它们给周围的人带来欢乐真的很有趣。",-1))]),s[38]||(s[38]=t("p",null,[i("这些命令能派上用场吗？我不确定是否可用，但你可以在 "),t("code",null,".bashrc"),i(" 文件中添加其中一些，这样一旦打开终端会话，命令就会立即运行。")],-1)),s[39]||(s[39]=t("p",null,[i("许多系统管理员在共享的 Linux 系统上都会这样做。像 "),t("code",null,"cowsay"),i(" 或 "),t("code",null,"figlet"),i(" 这样的程序可以用来以漂亮的方式显示消息或系统概况。")],-1)),s[40]||(s[40]=t("p",null,"你也可以在你的 Bash 脚本中使用其中的一些程序，尤其是当你需要突出显示某些内容时。",-1)),s[41]||(s[41]=t("p",null,"ASCII 字符画在 Linux 中可能还会有其他用途。你可以与我们分享。",-1)),s[42]||(s[42]=t("hr",null,null,-1)),t("p",null,[s[19]||(s[19]=i("via: ",-1)),e(a,{href:"https://itsfoss.com/ascii-art-linux-terminal/"},{default:l(()=>[...s[18]||(s[18]=[i("https://itsfoss.com/ascii-art-linux-terminal/",-1)])]),_:1})]),t("p",null,[s[24]||(s[24]=i("作者：",-1)),e(a,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...s[20]||(s[20]=[i("Abhishek Prakash",-1)])]),_:1}),s[25]||(s[25]=i(" 选题：",-1)),e(a,{href:"https://github.com/lkxed"},{default:l(()=>[...s[21]||(s[21]=[i("lkxed",-1)])]),_:1}),s[26]||(s[26]=i(" 译者：",-1)),e(a,{href:"https://github.com/CoWave-Fall"},{default:l(()=>[...s[22]||(s[22]=[i("泠知落汐",-1)])]),_:1}),s[27]||(s[27]=i(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[23]||(s[23]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[30]||(s[30]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[28]||(s[28]=[i("LCTT",-1)])]),_:1}),s[31]||(s[31]=i(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:l(()=>[...s[29]||(s[29]=[i("Linux中国",-1)])]),_:1}),s[32]||(s[32]=i(" 荣誉推出",-1))])])}const I=o(h,[["render",u]]);export{C as __pageData,I as default};
